   630      if (decode->context != ctxt || decode->part_index != part_index)
   631          return pctxt->report_error (
   632              pctxt,
   633              EXR_ERR_INVALID_ARGUMENT,
   634              "Invalid request for decoding update from different context / part");
   635
   636      if (!decode->read_fn)
   637          return pctxt->report_error (
   638              pctxt,
   639              EXR_ERR_INVALID_ARGUMENT,
   640              "Decode pipeline has no read_fn declared");
   641      rv = decode->read_fn (decode);
   642      if (rv != EXR_ERR_SUCCESS)
   643          return pctxt->report_error (
   644              pctxt, rv, "Unable to read pixel data block from context");
   645
   646      if (rv == EXR_ERR_SUCCESS) rv = update_pack_unpack_ptrs (decode);
   647      if (rv != EXR_ERR_SUCCESS)
