   650              rv,
   651              "Decode pipeline unable to update pack / unpack pointers");
   652
   653      if (rv == EXR_ERR_SUCCESS && decode->decompress_fn)
   654          rv = decode->decompress_fn (decode);
   655      if (rv != EXR_ERR_SUCCESS)
   656          return pctxt->report_error (
   657              pctxt, rv, "Decode pipeline unable to decompress data");
   658
   659      if (rv == EXR_ERR_SUCCESS &&
   660          (part->storage_mode == EXR_STORAGE_DEEP_SCANLINE ||
   661           part->storage_mode == EXR_STORAGE_DEEP_TILED))
   662      {
